mapper.insert:
INSERT INTO leetcode_mistake_review (
    mistake_id, fail_reason, fail_case, ai_analysis,
    action_plan, source_session_id
) VALUES (
    #{mistakeId}, #{failReason}, #{failCase}, #{aiAnalysis},
    #{actionPlan}, #{sourceSessionId}
)

mapper.select:
SELECT review.id, review.mistake_id, review.fail_reason, review.fail_case,
       review.ai_analysis, review.action_plan, review.source_session_id, review.created_at
FROM leetcode_mistake_review AS review
INNER JOIN leetcode_mistake AS mistake ON mistake.id = review.mistake_id
WHERE mistake.user_id = #{userId}


        AND mistake.id IN
        #{mistakeId}

    AND 1 = 0

ORDER BY review.created_at DESC, review.id DESC LIMIT #{limit}

mapper.delete:
DELETE review FROM leetcode_mistake_review AS review
INNER JOIN leetcode_mistake AS mistake ON mistake.id = review.mistake_id
WHERE review.mistake_id = #{mistakeId} AND mistake.user_id = #{userId}
